/**
 * SmartLens AI - Self-Contained 3D Particle Background System
 * Implements window.THREE as a marker stub so app.js skips its own fallback,
 * then immediately boots a stunning WebGL/Canvas particle field on #bg-canvas.
 *
 * Particles: 1800 white/blue dots in simulated 3D space
 * Features  : depth-based size & opacity, mouse parallax, connecting lines,
 *             slow rotation, 60 fps via requestAnimationFrame
 */

(function () {
  'use strict';

  /* ── Marker so app.js detects THREE is "present" ── */
  window.THREE = {
    _smartlensStub: true,
    Scene: function () { return {}; },
    PerspectiveCamera: function () { return {}; },
    WebGLRenderer: function () { return { setSize: function(){}, setPixelRatio: function(){}, render: function(){} }; },
    BufferGeometry: function () { return { setAttribute: function(){} }; },
    BufferAttribute: function () { return {}; },
    PointsMaterial: function () { return {}; },
    Points: function () { return { rotation: {x:0,y:0,z:0} }; },
    Vector3: function (x,y,z) { return {x:x||0,y:y||0,z:z||0}; },
    Color: function () { return {}; },
    LineBasicMaterial: function () { return {}; },
    Line: function () { return { rotation: {x:0,y:0,z:0} }; },
    Group: function () {
      var children = [];
      return {
        children: children,
        rotation: {x:0,y:0,z:0},
        position: {x:0,y:0,z:0},
        add: function(o){ children.push(o); }
      };
    }
  };

  /* ══════════════════════════════════════════════════════════════════
     Particle Engine — initialises after DOM is ready
  ══════════════════════════════════════════════════════════════════ */

  var PARTICLE_COUNT   = 1800;
  var CONNECTION_DIST  = 120;   // px — max distance for drawing connection lines
  var MAX_CONNECTIONS  = 4;     // per particle to keep it fast
  var DEPTH_RANGE      = 600;   // simulated Z depth (0 … DEPTH_RANGE)
  var BASE_SPEED       = 0.18;  // px/frame drift speed
  var MOUSE_STRENGTH   = 0.045; // parallax multiplier
  var FOG_START        = 0.3;   // depth fraction at which particles start fading

  var canvas, ctx, W, H, cx, cy;
  var particles = [];
  var mouse = { x: 0, y: 0 };
  var target = { x: 0, y: 0 };   // smoothed mouse
  var raf;
  var frameCount = 0;

  /* ── Colour helpers ── */
  function hsl(h, s, l, a) {
    return 'hsla(' + h + ',' + s + '%,' + l + '%,' + (a === undefined ? 1 : a) + ')';
  }

  /* ── Single particle ── */
  function Particle() {
    this.reset(true);
  }

  Particle.prototype.reset = function (initial) {
    this.x  = Math.random() * W;
    this.y  = initial ? Math.random() * H : -4;
    this.z  = Math.random() * DEPTH_RANGE;          // 0 = close, DEPTH_RANGE = far
    this.vx = (Math.random() - 0.5) * BASE_SPEED;
    this.vy = Math.random() * BASE_SPEED * 0.4 + BASE_SPEED * 0.1;
    /* colour: white → electric-blue tinted */
    var hue = Math.random() < 0.6 ? 0 : (Math.random() * 50 + 195);  // white or blue-cyan
    var sat = hue === 0 ? 0 : Math.floor(Math.random() * 60 + 50);
    var lit = Math.floor(Math.random() * 25 + 70);
    this.hue = hue; this.sat = sat; this.lit = lit;
    this.twinkle      = Math.random() * Math.PI * 2;  // phase
    this.twinkleSpeed = Math.random() * 0.04 + 0.01;
    this.baseRadius   = Math.random() * 1.8 + 0.4;
  };

  Particle.prototype.update = function (parallaxX, parallaxY) {
    this.x += this.vx + parallaxX * (1 - this.z / DEPTH_RANGE) * 0.3;
    this.y += this.vy + parallaxY * (1 - this.z / DEPTH_RANGE) * 0.3;
    this.twinkle += this.twinkleSpeed;

    /* wrap horizontally, recycle from bottom vertically */
    if (this.x < -4)  this.x = W + 4;
    if (this.x > W+4) this.x = -4;
    if (this.y > H+4) this.reset(false);
  };

  Particle.prototype.draw = function () {
    var depth   = this.z / DEPTH_RANGE;             // 0 = close, 1 = far
    var scale   = 1 - depth * 0.7;                  // far particles are smaller
    var alpha   = depth < FOG_START
                    ? 1
                    : (1 - (depth - FOG_START) / (1 - FOG_START)) * 0.85 + 0.15;
    var twinkAlpha = alpha * (0.7 + 0.3 * Math.sin(this.twinkle));
    var r = this.baseRadius * scale;

    /* parallax offset already applied in update */
    var px = this.x;
    var py = this.y;

    /* glow for close particles */
    if (depth < 0.4 && r > 0.9) {
      var grd = ctx.createRadialGradient(px, py, 0, px, py, r * 4);
      grd.addColorStop(0,   hsl(this.hue, this.sat, this.lit, twinkAlpha * 0.5));
      grd.addColorStop(1,   hsl(this.hue, this.sat, this.lit, 0));
      ctx.beginPath();
      ctx.arc(px, py, r * 4, 0, Math.PI * 2);
      ctx.fillStyle = grd;
      ctx.fill();
    }

    /* core dot */
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fillStyle = hsl(this.hue, this.sat, this.lit, twinkAlpha);
    ctx.fill();
  };

  /* ── Draw connections ── */
  function drawConnections() {
    for (var i = 0; i < particles.length; i++) {
      var a = particles[i];
      var count = 0;
      for (var j = i + 1; j < particles.length && count < MAX_CONNECTIONS; j++) {
        var b   = particles[j];
        var dx  = a.x - b.x;
        var dy  = a.y - b.y;
        var d   = Math.sqrt(dx*dx + dy*dy);
        if (d < CONNECTION_DIST) {
          count++;
          var alpha = (1 - d / CONNECTION_DIST) * 0.18;
          /* average depth for colour */
          var depth = (a.z + b.z) / (2 * DEPTH_RANGE);
          var hue   = (a.hue + b.hue) / 2;
          var sat   = (a.sat + b.sat) / 2;
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.strokeStyle = hsl(hue, sat, 80, alpha * (1 - depth * 0.6));
          ctx.lineWidth   = (1 - depth) * 0.8;
          ctx.stroke();
        }
      }
    }
  }

  /* ── Slow global rotation (fake 3D rotation of positions) ── */
  var rotAngle = 0;
  function applyGlobalRotation() {
    rotAngle += 0.00018;
    var cos = Math.cos(rotAngle), sin = Math.sin(rotAngle);
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      /* rotate about canvas centre */
      var dx = p.x - cx, dy = p.y - cy;
      p.x = cx + dx * cos - dy * sin;
      p.y = cy + dx * sin + dy * cos;
    }
  }

  /* ── Main loop ── */
  function loop() {
    raf = requestAnimationFrame(loop);
    frameCount++;

    /* smooth mouse */
    target.x += (mouse.x - target.x) * 0.06;
    target.y += (mouse.y - target.y) * 0.06;

    var parallaxX = (target.x - cx) * MOUSE_STRENGTH;
    var parallaxY = (target.y - cy) * MOUSE_STRENGTH * 0.5;

    /* clear with semi-transparent fill for trail effect */
    ctx.fillStyle = 'rgba(10,10,26,0.40)';
    ctx.fillRect(0, 0, W, H);

    /* apply subtle global rotation every 3 frames */
    if (frameCount % 3 === 0) applyGlobalRotation();

    /* update & draw — sort by z so far particles render first */
    for (var i = 0; i < particles.length; i++) {
      particles[i].update(parallaxX, parallaxY);
    }

    /* connection lines (every other frame for perf) */
    if (frameCount % 2 === 0) {
      ctx.save();
      drawConnections();
      ctx.restore();
    }

    /* draw particles front-to-back so glows layer correctly */
    for (var i = 0; i < particles.length; i++) {
      particles[i].draw();
    }

    /* subtle radial vignette */
    if (frameCount % 60 === 0 || frameCount === 1) {
      /* only rebuild gradient once per second */
      SmartLensParticles._vigGrd = (function(){
        var g = ctx.createRadialGradient(cx, cy, H*0.3, cx, cy, H*0.9);
        g.addColorStop(0, 'rgba(10,10,26,0)');
        g.addColorStop(1, 'rgba(10,10,26,0.55)');
        return g;
      })();
    }
    if (SmartLensParticles._vigGrd) {
      ctx.fillStyle = SmartLensParticles._vigGrd;
      ctx.fillRect(0, 0, W, H);
    }
  }

  /* ── Resize handler ── */
  function resize() {
    W  = canvas.width  = window.innerWidth;
    H  = canvas.height = window.innerHeight;
    cx = W / 2;
    cy = H / 2;
    SmartLensParticles._vigGrd = null;  // force rebuild
  }

  /* ── Bootstrap ── */
  var SmartLensParticles = {
    _vigGrd: null,

    init: function () {
      canvas = document.getElementById('bg-canvas');
      if (!canvas) return;   // no canvas on this page — skip silently

      ctx = canvas.getContext('2d');
      resize();

      /* spawn particles */
      particles = [];
      for (var i = 0; i < PARTICLE_COUNT; i++) {
        particles.push(new Particle());
      }

      /* sort by z descending so far particles are first in array
         (they get drawn first, close ones on top) */
      particles.sort(function(a,b){ return b.z - a.z; });

      /* events */
      window.addEventListener('resize', function () {
        resize();
        /* redistribute positions on resize */
        for (var i = 0; i < particles.length; i++) {
          if (particles[i].x > W) particles[i].x = Math.random() * W;
          if (particles[i].y > H) particles[i].y = Math.random() * H;
        }
      });

      window.addEventListener('mousemove', function (e) {
        mouse.x = e.clientX;
        mouse.y = e.clientY;
      });

      /* touch support */
      window.addEventListener('touchmove', function (e) {
        if (e.touches.length > 0) {
          mouse.x = e.touches[0].clientX;
          mouse.y = e.touches[0].clientY;
        }
      }, { passive: true });

      /* start */
      loop();
    },

    destroy: function () {
      if (raf) cancelAnimationFrame(raf);
    }
  };

  /* ── Wait for DOM then boot ── */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      SmartLensParticles.init();
    });
  } else {
    SmartLensParticles.init();
  }

  /* expose for debugging */
  window.SmartLensParticles = SmartLensParticles;

})();
